CREATE TABLE IF NOT EXISTS schema_versions(version int PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE companies(id bigserial PRIMARY KEY,name text NOT NULL UNIQUE CHECK(length(name) BETWEEN 1 AND 120),kind text NOT NULL DEFAULT 'Self' CHECK(kind IN ('Self','Group','Sub company')),status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected')));
CREATE TABLE teams(id bigserial PRIMARY KEY,company_id bigint NOT NULL REFERENCES companies,name text NOT NULL,UNIQUE(company_id,name),UNIQUE(id,company_id));
CREATE TABLE buyers(id bigserial PRIMARY KEY,company_id bigint NOT NULL REFERENCES companies,team_id bigint NOT NULL,name text NOT NULL,FOREIGN KEY(team_id,company_id) REFERENCES teams(id,company_id),UNIQUE(id,company_id));
CREATE TABLE lines(id bigserial PRIMARY KEY,company_id bigint NOT NULL REFERENCES companies,name text NOT NULL,capacity int NOT NULL DEFAULT 500 CHECK(capacity>0),UNIQUE(company_id,name),UNIQUE(id,company_id));
CREATE TABLE users(id bigserial PRIMARY KEY,username text NOT NULL UNIQUE,name text NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('MD','CEO','Finance','Marketing','Planning','Development','Sourcing','Stores','Sampling','Cutting','Production','Finishing','Quality','Warehouse')),scope text NOT NULL CHECK(scope IN ('company','team','line','po')),companies bigint[] NOT NULL DEFAULT '{}',teams bigint[] NOT NULL DEFAULT '{}',lines bigint[] NOT NULL DEFAULT '{}',orders bigint[] NOT NULL DEFAULT '{}',finishing_units text[] NOT NULL DEFAULT '{}',active boolean NOT NULL DEFAULT true,session_version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders(id bigserial PRIMARY KEY,company_id bigint NOT NULL REFERENCES companies,buyer_id bigint NOT NULL,team_id bigint NOT NULL,po text NOT NULL CHECK(length(po) BETWEEN 1 AND 60),style text NOT NULL CHECK(length(style) BETWEEN 1 AND 150),product text NOT NULL CHECK(product IN ('Suits','Trousers','Shirts','General')),quantity int NOT NULL CHECK(quantity>0 AND quantity<=10000000),due_date date NOT NULL,stage text NOT NULL DEFAULT 'Development' CHECK(stage IN ('Development','Sampling','Planning','Cutting','Sewing','Finishing','Packing','Warehouse','Invoiced','Dispatched')),approval text NOT NULL DEFAULT 'Pending' CHECK(approval IN ('Pending','Approved','Rejected')),line_id bigint,finishing_unit text NOT NULL DEFAULT '',sub_line text NOT NULL DEFAULT '',cutting_table text NOT NULL DEFAULT '',marker text NOT NULL DEFAULT '',unit_price_minor bigint NOT NULL DEFAULT 0 CHECK(unit_price_minor>=0),currency text NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','INR','EUR','GBP')),notes text NOT NULL DEFAULT '',invoice_number text NOT NULL DEFAULT '',dispatch_reference text NOT NULL DEFAULT '',version int NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(company_id,po),UNIQUE(id,company_id),FOREIGN KEY(buyer_id,company_id) REFERENCES buyers(id,company_id),FOREIGN KEY(team_id,company_id) REFERENCES teams(id,company_id),FOREIGN KEY(line_id,company_id) REFERENCES lines(id,company_id));
CREATE TABLE milestones(id bigserial PRIMARY KEY,order_id bigint NOT NULL REFERENCES orders,title text NOT NULL,due_date date NOT NULL,done boolean NOT NULL DEFAULT false);
CREATE TABLE work_items(id bigserial PRIMARY KEY,order_id bigint NOT NULL REFERENCES orders,kind text NOT NULL CHECK(kind IN ('Style development','CAD / pattern','Proto sample','Fit sample','Pre-production sample')),title text NOT NULL,status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','In progress','Approved','Changes needed')),notes text NOT NULL DEFAULT '');
CREATE TABLE entries(id bigserial PRIMARY KEY,order_id bigint NOT NULL REFERENCES orders,stage text NOT NULL CHECK(stage IN ('Cutting','Sewing','Finishing','Packing')),good int NOT NULL CHECK(good>=0),rework int NOT NULL CHECK(rework>=0),note text NOT NULL DEFAULT '',created_by bigint NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),CHECK(good+rework>0));
CREATE TABLE quality(id bigserial PRIMARY KEY,order_id bigint NOT NULL REFERENCES orders,stage text NOT NULL,inspected int NOT NULL CHECK(inspected>0),defects int NOT NULL CHECK(defects>=0 AND defects<=inspected),result text NOT NULL CHECK(result IN ('Pass','Hold','Rework')),notes text NOT NULL DEFAULT '',created_by bigint NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE suppliers(id bigserial PRIMARY KEY,company_id bigint NOT NULL REFERENCES companies,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 150),category text NOT NULL,designation text NOT NULL CHECK(designation IN ('Nominated','Direct','Non-nominated')),buyer_id bigint,contact text NOT NULL DEFAULT '',UNIQUE(company_id,name),UNIQUE(id,company_id),FOREIGN KEY(buyer_id,company_id) REFERENCES buyers(id,company_id),CHECK(designation<>'Nominated' OR buyer_id IS NOT NULL));
CREATE TABLE inventory(id bigserial PRIMARY KEY,company_id bigint NOT NULL REFERENCES companies,sku text NOT NULL,name text NOT NULL,store text NOT NULL CHECK(store IN ('Fabric','Trims')),unit text NOT NULL CHECK(unit IN ('metres','pieces','rolls','sets')),reorder_hundredths bigint NOT NULL DEFAULT 0 CHECK(reorder_hundredths>=0),UNIQUE(company_id,sku),UNIQUE(id,company_id));
CREATE TABLE movements(id bigserial PRIMARY KEY,item_id bigint NOT NULL REFERENCES inventory,quantity_hundredths bigint NOT NULL CHECK(quantity_hundredths<>0),kind text NOT NULL CHECK(kind IN ('Receipt','Issue')),order_id bigint REFERENCES orders,reference text NOT NULL CHECK(length(reference)>0),created_by bigint NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),CHECK((kind='Receipt' AND quantity_hundredths>0) OR (kind='Issue' AND quantity_hundredths<0 AND order_id IS NOT NULL)));
CREATE TABLE materials(id bigserial PRIMARY KEY,order_id bigint NOT NULL REFERENCES orders,item_id bigint NOT NULL REFERENCES inventory,quantity_hundredths bigint NOT NULL CHECK(quantity_hundredths>0));
CREATE TABLE purchases(id bigserial PRIMARY KEY,company_id bigint NOT NULL REFERENCES companies,reference text NOT NULL,supplier_id bigint NOT NULL,item_id bigint NOT NULL,order_id bigint,quantity_hundredths bigint NOT NULL CHECK(quantity_hundredths>0),unit_cost_minor bigint NOT NULL CHECK(unit_cost_minor>=0),due_date date NOT NULL,status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Received','Rejected')),created_by bigint NOT NULL REFERENCES users,UNIQUE(company_id,reference),FOREIGN KEY(supplier_id,company_id) REFERENCES suppliers(id,company_id),FOREIGN KEY(item_id,company_id) REFERENCES inventory(id,company_id),FOREIGN KEY(order_id,company_id) REFERENCES orders(id,company_id));
CREATE TABLE documents(id bigserial PRIMARY KEY,order_id bigint NOT NULL REFERENCES orders,name text NOT NULL,storage_key text NOT NULL UNIQUE,size bigint NOT NULL CHECK(size>0),sha256 text NOT NULL,created_by bigint NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit(id bigserial PRIMARY KEY,company_id bigint REFERENCES companies,actor_id bigint REFERENCES users,action text NOT NULL,entity text NOT NULL,entity_id bigint,detail text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reminders(order_id bigint NOT NULL REFERENCES orders,milestone_id bigint NOT NULL REFERENCES milestones,due_date date NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(order_id,milestone_id));
CREATE INDEX orders_scope_idx ON orders(company_id,team_id,line_id);
CREATE INDEX orders_due_idx ON orders(due_date);
CREATE INDEX entries_order_idx ON entries(order_id,stage);
CREATE INDEX movements_item_idx ON movements(item_id);
CREATE INDEX audit_company_idx ON audit(company_id,created_at DESC);
CREATE INDEX documents_order_idx ON documents(order_id);
CREATE OR REPLACE FUNCTION protect_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit records are append-only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION protect_audit();
INSERT INTO schema_versions(version) VALUES(1);
